class Solution {
  public int countBinaryPalindromes(long n) {
    if (n == 0) return 1;
    int L = 64 - Long.numberOfLeadingZeros(n);
    long total = 1;
    for (int len = 1; len < L; len++) total += 1L << ((len + 1) / 2 - 1);
    int half = (L + 1) / 2;
    long prefix = n >> (L - half);
    total += prefix - (1L << (half - 1));
    long tail = prefix >> (L % 2);
    long rev = 0;
    for (int i = 0; i < L - half; i++) {
      rev = (rev << 1) | (tail & 1);
      tail >>= 1;
    }
    long pal = (prefix << (L - half)) | rev;
    if (pal <= n) total++;
    return (int) total;
  }
}
